1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"strings"
10	
11		"github.com/entireio/cli/cmd/entire/cli/api"
12		"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
13		"github.com/entireio/cli/cmd/entire/cli/strategy"
14	
15		"github.com/spf13/cobra"
16	)
17	
18	// trailResumeActionReport is the --json payload for an actual resume: what was
19	// done, what was restored, and how to continue. Inspection (--no-resume
20	// --json) keeps its separate, richer context payload.
21	type trailResumeActionReport struct {
22		Trail        trailResumeReportTrail   `json:"trail"`
23		Actions      trailResumeReportActions `json:"actions"`
24		Continuation *trailResumeContinuation `json:"continuation,omitempty"`
25		Error        *trailResumeReportError  `json:"error,omitempty"`
26	}
27	
28	type trailResumeReportTrail struct {
29		ID     string `json:"id,omitempty"`
30		Number int    `json:"number,omitempty"`
31		Title  string `json:"title,omitempty"`
32		Branch string `json:"branch"`
33	}
34	
35	type trailResumeReportActions struct {
36		FetchedBranch        bool                       `json:"fetched_branch"`
37		SwitchedBranch       bool                       `json:"switched_branch"`
38		CheckpointID         string                     `json:"checkpoint_id,omitempty"`
39		CheckpointBehindHead int                        `json:"checkpoint_behind_head,omitempty"`
40		RestoredSessions     []trailResumeReportSession `json:"restored_sessions"`
41	}
42	
43	type trailResumeReportSession struct {
44		SessionID string `json:"session_id"`
45		Agent     string `json:"agent,omitempty"`
46		Kind      string `json:"kind,omitempty"`
47	}
48	
49	// trailResumeContinuation names the default session to continue with. Agent
50	// and session id are separate fields so headless orchestrators can construct
51	// their own invocation instead of unquoting the command string.
52	type trailResumeContinuation struct {
53		Agent     string `json:"agent,omitempty"`
54		SessionID string `json:"session_id"`
55		Command   string `json:"command,omitempty"`
56	}
57	
58	// trailResumeReportError is the typed-failure half of the JSON contract:
59	// typed resume errors emit the report with this error object and a non-zero
60	// exit; untyped/pre-action failures keep stdout empty with text on stderr.
61	type trailResumeReportError struct {
62		Type         string `json:"type"`
63		Message      string `json:"message"`
64		Branch       string `json:"branch,omitempty"`
65		WorktreePath string `json:"worktree_path,omitempty"`
66		CheckpointID string `json:"checkpoint_id,omitempty"`
67		SessionID    string `json:"session_id,omitempty"`
68	}
69	
70	// trailResumeReportErrorFrom maps a typed resume error to its JSON object,
71	// or nil when the error is not part of the typed contract.
72	func trailResumeReportErrorFrom(err error) *trailResumeReportError {
73		var clash *ResumeWorktreeClashError
74		if errors.As(err, &clash) {
75			return &trailResumeReportError{
76				Type:         "worktree_clash",
77				Message:      clash.Error(),
78				Branch:       clash.Branch,
79				WorktreePath: clash.WorktreePath,
80			}
81		}
82		var noCheckpoint *ResumeNoCheckpointError
83		if errors.As(err, &noCheckpoint) {
84			return &trailResumeReportError{
85				Type:    "no_checkpoint",
86				Message: noCheckpoint.Error(),
87				Branch:  noCheckpoint.Branch,
88			}
89		}
90		var unavailable *ResumeMetadataUnavailableError
91		if errors.As(err, &unavailable) {
92			return &trailResumeReportError{
93				Type:         "metadata_unavailable",
94				Message:      unavailable.Error(),
95				CheckpointID: unavailable.CheckpointID.String(),
96			}
97		}
98		var sessionNotFound *ResumeSessionNotFoundError
99		if errors.As(err, &sessionNotFound) {
100			return &trailResumeReportError{
101				Type:      "session_not_found",
102				Message:   sessionNotFound.Error(),
103				SessionID: sessionNotFound.SessionID,
104			}
105		}
106		var noSessions *ResumeNoSessionsRestoredError
107		if errors.As(err, &noSessions) {
108			return &trailResumeReportError{
109				Type:    "no_sessions_restored",
110				Message: noSessions.Error(),
111			}
112		}
113		return nil
114	}
115	
116	func buildTrailResumeActionReport(
117		found api.TrailResource,
118		branch string,
119		actions trailResumeReportActions,
120		sessions []strategy.RestoredSession,
121		preferredSessionID string,
122	) trailResumeActionReport {
123		report := trailResumeActionReport{
124			Trail: trailResumeReportTrail{
125				ID:     strings.TrimSpace(found.ID),
126				Number: found.Number,
127				Title:  strings.TrimSpace(found.Title),
128				Branch: strings.TrimSpace(branch),
129			},
130			Actions: actions,
131		}
132		report.Actions.RestoredSessions = make([]trailResumeReportSession, 0, len(sessions))
133		for _, session := range sessions {
134			report.Actions.RestoredSessions = append(report.Actions.RestoredSessions, trailResumeReportSession{
135				SessionID: session.SessionID,
136				Agent:     string(session.Agent),
137				Kind:      session.Kind,
138			})
139		}
140		if report.Actions.CheckpointID == "" {
141			report.Actions.CheckpointID = restoredSessionsCheckpointID(sessions)
142		}
143		report.Continuation = trailResumeContinuationFor(sessions, preferredSessionID)
144		return report
145	}
146	
147	func trailResumeContinuationFor(sessions []strategy.RestoredSession, preferredSessionID string) *trailResumeContinuation {
148		if len(sessions) == 0 {
149			return nil
150		}
151		choice := buildTrailResumeRestoredSessionChoices(sessions)[0].Session
152		if preferredSessionID != "" {
153			if preferred, ok := findTrailRestoredSession(sessions, preferredSessionID); ok {
154				choice = preferred
155			}
156		}
157		continuation := &trailResumeContinuation{
158			Agent:     string(choice.Agent),
159			SessionID: choice.SessionID,
160		}
161		if sessionAgent, err := strategy.ResolveAgentForRewind(choice.Agent); err == nil {
162			continuation.Command = sessionAgent.FormatResumeCommand(choice.SessionID)
163		}
164		return continuation
165	}
166	
167	// runTrailResumeJSON drives an actual resume with a JSON action report on
168	// stdout. Human act-path output is suppressed (warnings stay on stderr);
169	// typed failures emit the report with an error object and exit non-zero.
170	func runTrailResumeJSON(ctx context.Context, cmd *cobra.Command, found api.TrailResource, branch string, opts trailResumeOptions) error {
171		errW := cmd.ErrOrStderr()
172	
173		var actions trailResumeReportActions
174		var restored []strategy.RestoredSession
175		emit := func(report trailResumeActionReport) error {
176			enc := json.NewEncoder(cmd.OutOrStdout())
177			enc.SetEscapeHTML(false)
178			enc.SetIndent("", "  ")
179			if err := enc.Encode(report); err != nil {
180				return fmt.Errorf("encode trail resume action report: %w", err)
181			}
182			return nil
183		}
184		// fail emits the report with whatever side effects already happened
185		// (branch switch, restored sessions) so a typed failure never hides real
186		// state changes from the caller.
187		fail := func(err error) error {
188			reportErr := trailResumeReportErrorFrom(err)
189			if reportErr == nil {
190				return err
191			}
192			report := buildTrailResumeActionReport(found, branch, actions, restored, "")
193			report.Continuation = nil
194			report.Error = reportErr
195			if encodeErr := emit(report); encodeErr != nil {
196				return encodeErr
197			}
198			return NewSilentError(err)
199		}
200	
201		if err := ensureTrailResumeBranchAvailable(ctx, errW, branch); err != nil {
202			return fail(err)
203		}
204	
205		// Best-effort fact for the report: on detached HEAD (or any read failure)
206		// there is no current branch, so a successful checkout below did switch.
207		currentBranch, branchErr := GetCurrentBranch(ctx)
208		if branchErr != nil {
209			currentBranch = ""
210		}
211		existedLocally, existsErr := BranchExistsLocally(ctx, branch)
212		if existsErr != nil {
213			existedLocally = true
214		}
215		proceed, err := switchToBranchForResume(ctx, io.Discard, errW, branch, true)
216		if err != nil {
217			return fail(err)
218		}
219		if !proceed {
220			return errors.New("resume stopped before switching branches")
221		}
222		actions.SwitchedBranch = currentBranch != branch
223		actions.FetchedBranch = !existedLocally
224		// behind-head describes the branch's LATEST checkpoint; --checkpoint and
225		// --session may resume an older one, for which the count would mislead.
226		if opts.CheckpointID == "" && opts.SessionID == "" {
227			actions.CheckpointBehindHead = trailResumeCheckpointBehindHead(ctx, branch)
228		}
229	
230		sessions, preferred, err := restoreTrailSessionsForReport(ctx, errW, branch, opts)
231		if err != nil {
232			return fail(err)
233		}
234		restored = sessions
235		if len(sessions) == 0 {
236			// The checkpoint resolved but its restore produced nothing (e.g.
237			// session log content unavailable): success-with-empty-report would
238			// break the "non-zero whenever nothing was resumed" contract.
239			return fail(&ResumeNoSessionsRestoredError{})
240		}
241		if err := ensurePreferredRestoredSession(sessions, preferred); err != nil {
242			return fail(err)
243		}
244	
245		return emit(buildTrailResumeActionReport(found, branch, actions, sessions, preferred))
246	}
247	
248	// ensurePreferredRestoredSession rejects a --session id that is not among the
249	// restored sessions, mirroring the human path's continueRestoredSessions
250	// error — the JSON contract must never point the continuation at a different
251	// session than the one requested.
252	func ensurePreferredRestoredSession(sessions []strategy.RestoredSession, preferredSessionID string) error {
253		if preferredSessionID == "" {
254			return nil
255		}
256		if _, ok := findTrailRestoredSession(sessions, preferredSessionID); ok {
257			return nil
258		}
259		return &ResumeSessionNotFoundError{SessionID: preferredSessionID}
260	}
261	
262	// trailResumeCheckpointBehindHead reports how many branch commits are newer
263	// than the latest checkpointed commit (0 when HEAD has the checkpoint or the
264	// count cannot be determined; best-effort).
265	func trailResumeCheckpointBehindHead(ctx context.Context, branch string) int {
266		repo, err := openRepository(ctx)
267		if err != nil {
268			return 0
269		}
270		defer repo.Close()
271		result, err := findBranchCheckpoints(repo, branch)
272		if err != nil || result == nil || !result.newerCommitsExist {
273			return 0
274		}
275		return result.newerCommitCount
276	}
277	
278	// restoreTrailSessionsForReport performs the restore for the JSON act path,
279	// applying the same --checkpoint / --session / latest selection as the human
280	// act path but with human output discarded.
281	func restoreTrailSessionsForReport(ctx context.Context, errW io.Writer, branch string, opts trailResumeOptions) ([]strategy.RestoredSession, string, error) {
282		if opts.CheckpointID != "" {
283			sessions, err := restoreByCheckpointID(ctx, io.Discard, errW, id.CheckpointID(opts.CheckpointID), opts.Force)
284			return sessions, "", err
285		}
286		if opts.SessionID != "" {
287			contexts, _, ctxErr := resolveTrailResumeSessionContexts(ctx, branch)
288			if ctxErr == nil {
289				if sessionCtx, ok := findTrailResumeSession(contexts, opts.SessionID); ok {
290					sessions, err := restoreByCheckpointID(ctx, io.Discard, errW, id.CheckpointID(sessionCtx.CheckpointID), opts.Force)
291					return sessions, opts.SessionID, err
292				}
293			} else {
294				fmt.Fprintf(errW, "Warning: could not load trail checkpoint sessions: %v\n", ctxErr)
295			}
296			sessions, err := restoreFromCurrentBranch(ctx, io.Discard, errW, branch, opts.Force, false)
297			return sessions, opts.SessionID, err
298		}
299		sessions, err := restoreFromCurrentBranch(ctx, io.Discard, errW, branch, opts.Force, false)
300		return sessions, "", err
301	}
